insert into public.absorption_factors
  (nutrient_id, condition_key, factor, low, high, description, source_citation)
values
  ('iron', 'heme_share', 0.4, 0.4, 0.4, 'Share of the iron in meat, poultry and fish that is heme iron.', 'Monsen ER et al. Estimation of available dietary iron. Am J Clin Nutr 1978;31:134-41'),
  ('iron', 'heme_absorption', 0.23, 0.15, 0.35, 'Fraction of heme iron absorbed: 23% at 500 mg iron stores; 15% (1000 mg stores) to 35% (no stores).', 'Monsen ER et al. Estimation of available dietary iron. Am J Clin Nutr 1978;31:134-41'),
  ('iron', 'nonheme_base', 0.03, 0.03, 0.03, 'Non-heme iron absorbed from a meal with no enhancers (500 mg iron stores).', 'Monsen ER, Balintfy JL. Calculating dietary iron bioavailability: refinement and computerization. J Am Diet Assoc 1982;80:307-11'),
  ('iron', 'nonheme_ef_slope', 0.0893, 0.0893, 0.0893, 'Slope of the enhancer curve: absorption = base + slope x ln((EF + 100) / 100), EF = mg vitamin C + g meat/fish/poultry.', 'Monsen ER, Balintfy JL. Calculating dietary iron bioavailability: refinement and computerization. J Am Diet Assoc 1982;80:307-11'),
  ('iron', 'nonheme_ef_cap', 75, 75, 75, 'Enhancing-factor units (mg vitamin C + g meat/fish/poultry) above which absorption no longer rises (8%).', 'Monsen ER, Balintfy JL. Calculating dietary iron bioavailability: refinement and computerization. J Am Diet Assoc 1982;80:307-11'),
  ('iron', 'nonheme_store_scale', 1, 0.65, 1.52, 'Scales non-heme absorption for iron status, using the same ratios as heme (15/23 and 35/23) because iron status is not known.', 'Monsen ER et al. Estimation of available dietary iron. Am J Clin Nutr 1978;31:134-41; Modelling assumption (see docs/bioavailability.md)'),
  ('iron', 'mfp_grams_per_g_protein', 4, 3.3, 5, 'Grams of cooked meat, poultry or fish per gram of protein (cooked lean meats are about 20-30% protein), used to estimate the meat content of mixed dishes.', 'USDA FoodData Central SR Legacy cooked meats; Modelling assumption (see docs/bioavailability.md)'),
  ('iron', 'phytate_p_share', 0.2816, 0.2816, 0.2816, 'Phosphorus share of phytic acid by mass (6 x 30.97 / 660.04), to convert phytate to phytate phosphorus.', 'Phytic acid formula C6H18O24P6 (molar mass 660.04 g/mol)'),
  ('iron', 'phytate_p_mg:0', 1, 1, 1, 'Non-heme iron absorption remaining with no phytate.', 'Hallberg L, Brune M, Rossander L. Iron absorption in man: ascorbic acid and dose-dependent inhibition by phytate. Am J Clin Nutr 1989;49:140-4'),
  ('iron', 'phytate_p_mg:2', 0.82, 0.82, 0.82, 'Non-heme iron absorption remaining with 2 mg phytate phosphorus (18% lower).', 'Hallberg L, Brune M, Rossander L. Iron absorption in man: ascorbic acid and dose-dependent inhibition by phytate. Am J Clin Nutr 1989;49:140-4'),
  ('iron', 'phytate_p_mg:25', 0.36, 0.36, 0.36, 'Non-heme iron absorption remaining with 25 mg phytate phosphorus (64% lower).', 'Hallberg L, Brune M, Rossander L. Iron absorption in man: ascorbic acid and dose-dependent inhibition by phytate. Am J Clin Nutr 1989;49:140-4'),
  ('iron', 'phytate_p_mg:250', 0.18, 0.18, 0.18, 'Non-heme iron absorption remaining with 250 mg phytate phosphorus (82% lower).', 'Hallberg L, Brune M, Rossander L. Iron absorption in man: ascorbic acid and dose-dependent inhibition by phytate. Am J Clin Nutr 1989;49:140-4'),
  ('iron', 'tea_remaining', 0.38, 0.36, 0.38, 'Non-heme iron absorption remaining when tea is drunk with a meal (62-64% lower).', 'Hallberg L, Rossander L. Effect of different drinks on the absorption of non-heme iron from composite meals. Hum Nutr Appl Nutr 1982;36:116-23; Morck TA, Lynch SR, Cook JD. Inhibition of food iron absorption by coffee. Am J Clin Nutr 1983;37:416-20'),
  ('iron', 'coffee_remaining', 0.63, 0.61, 0.65, 'Non-heme iron absorption remaining when coffee is drunk with a meal (35-39% lower).', 'Hallberg L, Rossander L. Effect of different drinks on the absorption of non-heme iron from composite meals. Hum Nutr Appl Nutr 1982;36:116-23; Morck TA, Lynch SR, Cook JD. Inhibition of food iron absorption by coffee. Am J Clin Nutr 1983;37:416-20'),
  ('iron', 'drink_reference_g', 200, 200, 200, 'A cup of tea or coffee (g). Smaller amounts have a proportionally smaller effect.', 'Modelling assumption (see docs/bioavailability.md)'),
  ('iron', 'calcium_mg:0', 1, 1, 1, 'Non-heme iron absorption remaining with no calcium in the meal.', 'Hallberg L et al. Calcium: effect of different amounts on nonheme- and heme-iron absorption in humans. Am J Clin Nutr 1991;53:112-9'),
  ('iron', 'calcium_mg:165', 0.45, 0.4, 0.5, 'Non-heme iron absorption remaining with 165 mg calcium in the meal (50-60% lower); the effect is dose-related up to about 300 mg.', 'Hallberg L et al. Calcium: effect of different amounts on nonheme- and heme-iron absorption in humans. Am J Clin Nutr 1991;53:112-9'),
  ('iron', 'calcium_mg:600', 0.45, 0.4, 0.5, 'Non-heme iron absorption remaining with 300-600 mg calcium in the meal (50-60% lower, a plateau).', 'Hallberg L et al. Calcium: effect of different amounts on nonheme- and heme-iron absorption in humans. Am J Clin Nutr 1991;53:112-9'),
  ('phytate', 'mg_per_100g_dry:none', 0, 0, 0, 'No phytate.', 'Modelling assumption (see docs/bioavailability.md)'),
  ('phytate', 'mg_per_100g_dry:high', 1200, 500, 2900, 'Phytic acid in high-phytate foods (legumes, nuts, seeds, bran), per 100 g dry matter. Legumes range 0.2-2.9%.', 'DTU Food. Phytate - a natural component in plant food (2011); Schlemmer U et al. Phytate in foods and significance for humans. Mol Nutr Food Res 2009;53:S330-75'),
  ('phytate', 'mg_per_100g_dry:medium', 1000, 500, 2200, 'Phytic acid in whole grains, per 100 g dry matter. Cereals are typically about 1% (range 0.06-2.2%).', 'DTU Food. Phytate - a natural component in plant food (2011); Schlemmer U et al. Phytate in foods and significance for humans. Mol Nutr Food Res 2009;53:S330-75'),
  ('phytate', 'mg_per_100g_dry:low', 150, 60, 400, 'Phytic acid in refined grains, per 100 g dry matter: the low end of the cereal range.', 'DTU Food. Phytate - a natural component in plant food (2011); Schlemmer U et al. Phytate in foods and significance for humans. Mol Nutr Food Res 2009;53:S330-75; Modelling assumption (see docs/bioavailability.md)'),
  ('zinc', 'ratio_cutoff_high', 5, 5, 5, 'Phytate:zinc molar ratio below which zinc bioavailability is high.', 'FAO/WHO. Vitamin and mineral requirements in human nutrition, 2nd ed. (2004), ch. 12 Zinc, Tables 54-55'),
  ('zinc', 'ratio_cutoff_low', 15, 15, 15, 'Phytate:zinc molar ratio above which zinc bioavailability is low.', 'FAO/WHO. Vitamin and mineral requirements in human nutrition, 2nd ed. (2004), ch. 12 Zinc, Tables 54-55'),
  ('zinc', 'absorption_high', 0.5, 0.3, 0.5, 'Zinc absorbed when the phytate:zinc molar ratio is under 5.', 'FAO/WHO. Vitamin and mineral requirements in human nutrition, 2nd ed. (2004), ch. 12 Zinc, Tables 54-55; NIH Office of Dietary Supplements, Zinc Fact Sheet for Health Professionals (5% to more than 50%)'),
  ('zinc', 'absorption_moderate', 0.3, 0.15, 0.5, 'Zinc absorbed when the phytate:zinc molar ratio is 5-15.', 'FAO/WHO. Vitamin and mineral requirements in human nutrition, 2nd ed. (2004), ch. 12 Zinc, Tables 54-55; NIH Office of Dietary Supplements, Zinc Fact Sheet for Health Professionals'),
  ('zinc', 'absorption_low', 0.15, 0.05, 0.3, 'Zinc absorbed when the phytate:zinc molar ratio is over 15.', 'FAO/WHO. Vitamin and mineral requirements in human nutrition, 2nd ed. (2004), ch. 12 Zinc, Tables 54-55; NIH Office of Dietary Supplements, Zinc Fact Sheet for Health Professionals'),
  ('calcium', 'high_oxalate', 0.05, 0.05, 0.05, 'Calcium absorbed from high-oxalate greens such as spinach (about 5%).', 'NIH Office of Dietary Supplements, Calcium Fact Sheet for Health Professionals; Weaver CM, Proulx WR, Heaney R. Choices for achieving adequate dietary calcium with a vegetarian diet. Am J Clin Nutr 1999;70(suppl):543S-8S (spinach 5.1%)'),
  ('calcium', 'low_oxalate_greens', 0.53, 0.49, 0.61, 'Calcium absorbed from low-oxalate greens: kale 49%, bok choy 54%, broccoli 61%.', 'Weaver CM, Proulx WR, Heaney R. Choices for achieving adequate dietary calcium with a vegetarian diet. Am J Clin Nutr 1999;70(suppl):543S-8S'),
  ('calcium', 'dairy', 0.3, 0.27, 0.32, 'Calcium absorbed from dairy foods (about 30%; milk 27-32%).', 'NIH Office of Dietary Supplements, Calcium Fact Sheet for Health Professionals; Weaver CM, Proulx WR, Heaney R. Choices for achieving adequate dietary calcium with a vegetarian diet. Am J Clin Nutr 1999;70(suppl):543S-8S'),
  ('calcium', 'fortified', 0.3, 0.27, 0.32, 'Calcium absorbed from fortified foods (about 30%, similar to dairy).', 'NIH Office of Dietary Supplements, Calcium Fact Sheet for Health Professionals'),
  ('calcium', 'high_phytate_legumes', 0.24, 0.22, 0.27, 'Calcium absorbed from beans and other high-phytate legumes (22-27%).', 'Weaver CM, Proulx WR, Heaney R. Choices for achieving adequate dietary calcium with a vegetarian diet. Am J Clin Nutr 1999;70(suppl):543S-8S'),
  ('calcium', 'default', 0.25, 0.15, 0.45, 'Calcium absorbed from other foods: about 25% for adults; 45% at low intakes, 15% at very high intakes.', 'NIH Office of Dietary Supplements, Calcium Fact Sheet for Health Professionals'),
  ('fat_soluble', 'adequate_fat_g', 5, 3, 5, 'Grams of fat in a meal at which fat-soluble vitamin absorption is no longer limited by fat. Below it, the low-fat multiplier is phased in linearly.', 'Brown MJ et al. Carotenoid bioavailability is higher from salads ingested with full-fat than with fat-reduced salad dressings. Am J Clin Nutr 2004;80:396-403; Modelling assumption (see docs/bioavailability.md)'),
  ('vitamin_a', 'rae', 1, 1, 1, 'Vitamin A is reported by USDA as RAE, which already accounts for absorption and carotenoid conversion; no further factor is applied.', 'NIH Office of Dietary Supplements, Vitamin A Fact Sheet for Health Professionals; USDA FoodData Central nutrient 320 (RAE)'),
  ('vitamin_a', 'provitamin_low_fat', 0.1, 0, 0.3, 'Multiplier on vitamin A from carotenoids when a meal has almost no fat: absorption was negligible with fat-free dressing.', 'Brown MJ et al. Carotenoid bioavailability is higher from salads ingested with full-fat than with fat-reduced salad dressings. Am J Clin Nutr 2004;80:396-403; Modelling assumption (see docs/bioavailability.md) (exact value)'),
  ('vitamin_d', 'base', 1, 1, 1, 'Vitamin D in food is well absorbed; no reliable fractional figure exists, so it is counted as eaten when fat is present.', 'NIH Office of Dietary Supplements, Vitamin D Fact Sheet for Health Professionals'),
  ('vitamin_d', 'low_fat', 0.76, 0.66, 0.9, 'Multiplier on vitamin D with a fat-free meal: blood levels peaked 32% (11-52%) higher with a fat-containing meal.', 'Dawson-Hughes B et al. Dietary fat increases vitamin D-3 absorption. J Acad Nutr Diet 2015;115:225-30'),
  ('vitamin_e', 'base', 0.33, 0.28, 0.38, 'Vitamin E (alpha-tocopherol) absorbed with a meal containing fat (33 +/- 5%).', 'Bruno RS et al. Human vitamin E requirements assessed with the use of apples fortified with deuterium-labeled alpha-tocopheryl acetate. Am J Clin Nutr 2006;83:299-304'),
  ('vitamin_e', 'low_fat', 0.3, 0.18, 0.42, 'Multiplier on vitamin E with a fat-free meal: 10 +/- 4% absorbed vs 33% with fat.', 'Bruno RS et al. Human vitamin E requirements assessed with the use of apples fortified with deuterium-labeled alpha-tocopheryl acetate. Am J Clin Nutr 2006;83:299-304'),
  ('vitamin_k', 'base', 0.1, 0.03, 0.14, 'Vitamin K (phylloquinone) absorbed from foods: free phylloquinone is about 80% absorbed, and food phylloquinone 4-17% as well as a tablet.', 'NIH Office of Dietary Supplements, Vitamin K Fact Sheet for Health Professionals; Gijsbers BL, Jie KS, Vermeer C. Effect of food composition on vitamin K absorption in human volunteers. Br J Nutr 1996;76:223-9'),
  ('vitamin_k', 'low_fat', 0.31, 0.31, 0.31, 'Multiplier on vitamin K with no fat: spinach alone gave 4% of a tablet''s absorption vs 13% with butter.', 'Gijsbers BL, Jie KS, Vermeer C. Effect of food composition on vitamin K absorption in human volunteers. Br J Nutr 1996;76:223-9'),
  ('vitamin_b12', 'active_capacity_ug', 1.5, 1, 2, 'Most B12 absorbed per meal through intrinsic factor, which is saturated at about 1-2 mcg.', 'NIH Office of Dietary Supplements, Vitamin B12 Fact Sheet for Health Professionals'),
  ('vitamin_b12', 'half_saturation_ug', 2.06, 2.06, 2.06, 'Dose (mcg) at which intrinsic-factor absorption is half its maximum; set so that about 50% of a 1 mcg dose is absorbed.', 'NIH Office of Dietary Supplements, Vitamin B12 Fact Sheet for Health Professionals (about 50% at doses under 1-2 mcg); Modelling assumption (see docs/bioavailability.md) (curve shape)'),
  ('vitamin_b12', 'passive_fraction', 0.01, 0.01, 0.02, 'Fraction of B12 absorbed by passive diffusion, independent of intrinsic factor (about 1-2%).', 'NIH Office of Dietary Supplements, Vitamin B12 Fact Sheet for Health Professionals (2% at 500 mcg, 1.3% at 1000 mcg)'),
  ('vitamin_c', 'dose_mg:0', 0.8, 0.7, 0.9, 'Vitamin C absorbed at moderate intakes (70-90%).', 'NIH Office of Dietary Supplements, Vitamin C Fact Sheet for Health Professionals'),
  ('vitamin_c', 'dose_mg:180', 0.8, 0.7, 0.9, 'Vitamin C absorbed at up to 180 mg (70-90%).', 'NIH Office of Dietary Supplements, Vitamin C Fact Sheet for Health Professionals'),
  ('vitamin_c', 'dose_mg:1000', 0.45, 0.3, 0.5, 'Vitamin C absorbed at doses above 1 g: less than 50%.', 'NIH Office of Dietary Supplements, Vitamin C Fact Sheet for Health Professionals; Modelling assumption (see docs/bioavailability.md) (low end)'),
  ('copper', 'daily_mg:0.4', 0.75, 0.75, 0.75, 'Copper absorbed when the diet has 0.4 mg/day.', 'NIH Office of Dietary Supplements, Copper Fact Sheet for Health Professionals'),
  ('copper', 'daily_mg:7.5', 0.12, 0.12, 0.12, 'Copper absorbed when the diet has 7.5 mg/day.', 'NIH Office of Dietary Supplements, Copper Fact Sheet for Health Professionals'),
  ('magnesium', 'base', 0.35, 0.3, 0.4, 'Magnesium absorbed from food (30-40%).', 'NIH Office of Dietary Supplements, Magnesium Fact Sheet for Health Professionals'),
  ('potassium', 'base', 0.875, 0.85, 0.9, 'Potassium absorbed from food (85-90%).', 'NIH Office of Dietary Supplements, Potassium Fact Sheet for Health Professionals'),
  ('phosphorus', 'base', 0.55, 0.4, 0.7, 'Phosphorus absorbed from food (40-70%; higher from animal foods).', 'NIH Office of Dietary Supplements, Phosphorus Fact Sheet for Health Professionals'),
  ('chromium', 'base', 0.0145, 0.004, 0.025, 'Chromium absorbed from food (0.4-2.5%).', 'NIH Office of Dietary Supplements, Chromium Fact Sheet for Health Professionals'),
  ('manganese', 'base', 0.03, 0.01, 0.05, 'Manganese absorbed from food (1-5%).', 'NIH Office of Dietary Supplements, Manganese Fact Sheet for Health Professionals'),
  ('molybdenum', 'base', 0.7, 0.4, 1, 'Molybdenum absorbed from food (40-100%).', 'NIH Office of Dietary Supplements, Molybdenum Fact Sheet for Health Professionals'),
  ('iodine', 'base', 0.96, 0.96, 1, 'Iodine is absorbed almost completely (96% of potassium iodide).', 'NIH Office of Dietary Supplements, Iodine Fact Sheet for Health Professionals'),
  ('selenium', 'base', 0.9, 0.9, 0.9, 'Selenium absorbed from food forms such as selenomethionine (up to about 90%).', 'NIH Office of Dietary Supplements, Selenium Fact Sheet for Health Professionals'),
  ('sodium', 'base', 0.98, 0.98, 0.98, 'Sodium absorbed (about 98%).', 'NASEM. Dietary Reference Intakes for Sodium and Potassium (2019): about 98% of sodium and chloride is absorbed'),
  ('chloride', 'base', 0.98, 0.98, 0.98, 'Chloride absorbed (about 98%).', 'NASEM. Dietary Reference Intakes for Sodium and Potassium (2019): about 98% of sodium and chloride is absorbed'),
  ('riboflavin', 'base', 0.95, 0.95, 0.95, 'Riboflavin absorbed from food (about 95%, up to about 27 mg per meal).', 'NIH Office of Dietary Supplements, Riboflavin Fact Sheet for Health Professionals'),
  ('vitamin_b6', 'base', 0.75, 0.75, 0.75, 'Vitamin B6 absorbed from a mixed diet (about 75%).', 'NIH Office of Dietary Supplements, Vitamin B6 Fact Sheet for Health Professionals'),
  ('pantothenic_acid', 'base', 0.5, 0.4, 0.61, 'Pantothenic acid absorbed from food (40-61%, about half).', 'NIH Office of Dietary Supplements, Pantothenic Acid Fact Sheet for Health Professionals'),
  ('niacin', 'grains', 0.3, 0.3, 0.3, 'Niacin naturally present in grains is mostly bound and only about 30% available.', 'NIH Office of Dietary Supplements, Niacin Fact Sheet for Health Professionals'),
  ('niacin', 'base', 1, 1, 1, 'Niacin in other foods (and added niacin) is almost completely absorbed.', 'NIH Office of Dietary Supplements, Niacin Fact Sheet for Health Professionals'),
  ('thiamin', 'base', 1, 1, 1, 'Thiamin is actively absorbed at food doses; no fractional figure is published, so it is counted as eaten.', 'NIH Office of Dietary Supplements, Thiamin Fact Sheet for Health Professionals'),
  ('biotin', 'base', 1, 1, 1, 'Free biotin is absorbed completely.', 'NIH Office of Dietary Supplements, Biotin Fact Sheet for Health Professionals'),
  ('choline', 'base', 1, 1, 1, 'No estimate of choline absorption exists, so it is counted as eaten.', 'NIH Office of Dietary Supplements, Choline Fact Sheet for Health Professionals'),
  ('folate', 'dfe', 1, 1, 1, 'Folate is reported by USDA as DFE, which already accounts for the higher absorption of folic acid; no further factor is applied.', 'NIH Office of Dietary Supplements, Folate Fact Sheet for Health Professionals; USDA FoodData Central nutrient 435 (DFE)'),
  ('protein', 'egg', 0.97, 0.97, 0.97, 'Protein digestibility: egg.', 'WHO/FAO/UNU. Protein and amino acid requirements in human nutrition. WHO Technical Report Series 935 (2007), Table 5: true digestibility of protein in humans'),
  ('protein', 'dairy', 0.95, 0.95, 0.95, 'Protein digestibility: milk, cheese.', 'WHO/FAO/UNU. Protein and amino acid requirements in human nutrition. WHO Technical Report Series 935 (2007), Table 5: true digestibility of protein in humans'),
  ('protein', 'meat', 0.94, 0.94, 0.94, 'Protein digestibility: meat.', 'WHO/FAO/UNU. Protein and amino acid requirements in human nutrition. WHO Technical Report Series 935 (2007), Table 5: true digestibility of protein in humans'),
  ('protein', 'fish', 0.94, 0.94, 0.94, 'Protein digestibility: fish.', 'WHO/FAO/UNU. Protein and amino acid requirements in human nutrition. WHO Technical Report Series 935 (2007), Table 5: true digestibility of protein in humans'),
  ('protein', 'soy', 0.9, 0.86, 0.95, 'Protein digestibility: soy (soy flour 86%, soy protein isolate 95%).', 'WHO/FAO/UNU. Protein and amino acid requirements in human nutrition. WHO Technical Report Series 935 (2007), Table 5: true digestibility of protein in humans'),
  ('protein', 'legume', 0.78, 0.78, 0.88, 'Protein digestibility: beans 78%, mature peas 88%.', 'WHO/FAO/UNU. Protein and amino acid requirements in human nutrition. WHO Technical Report Series 935 (2007), Table 5: true digestibility of protein in humans'),
  ('protein', 'nut_seed', 0.94, 0.9, 0.95, 'Protein digestibility: peanuts 94%, peanut butter 95%, sunflower seed flour 90%.', 'WHO/FAO/UNU. Protein and amino acid requirements in human nutrition. WHO Technical Report Series 935 (2007), Table 5: true digestibility of protein in humans'),
  ('protein', 'grain', 0.86, 0.7, 0.99, 'Protein digestibility: whole wheat and oatmeal 86%, polished rice 88%, refined wheat 96%, corn cereal 70%.', 'WHO/FAO/UNU. Protein and amino acid requirements in human nutrition. WHO Technical Report Series 935 (2007), Table 5: true digestibility of protein in humans'),
  ('protein', 'default', 0.92, 0.77, 0.96, 'Protein digestibility for other foods: the Atwater mixed-diet coefficient (92%); measured mixed diets range 77-96%.', 'Merrill AL, Watt BK. Energy value of foods: basis and derivation. USDA Agriculture Handbook No. 74 (1955, rev. 1973): Atwater mixed-diet digestibility coefficients; WHO/FAO/UNU. Protein and amino acid requirements in human nutrition. WHO Technical Report Series 935 (2007), Table 5: true digestibility of protein in humans'),
  ('fat', 'base', 0.95, 0.9, 0.95, 'Fat digestibility (95% for a mixed diet; 90-95% across foods).', 'Merrill AL, Watt BK. Energy value of foods: basis and derivation. USDA Agriculture Handbook No. 74 (1955, rev. 1973): Atwater mixed-diet digestibility coefficients'),
  ('carbohydrate', 'base', 0.97, 0.97, 0.97, 'Digestibility of carbohydrate other than fiber (97% for a mixed diet).', 'Merrill AL, Watt BK. Energy value of foods: basis and derivation. USDA Agriculture Handbook No. 74 (1955, rev. 1973): Atwater mixed-diet digestibility coefficients'),
  ('energy', 'base', 1, 1, 1, 'USDA calories use Atwater factors, which already allow for digestibility; no further factor is applied.', 'Merrill AL, Watt BK. Energy value of foods: basis and derivation. USDA Agriculture Handbook No. 74 (1955, rev. 1973): Atwater mixed-diet digestibility coefficients'),
  ('cholesterol', 'base', 0.55, 0.41, 0.7, 'Cholesterol absorbed (women 53%, men 58%, SD about 12%).', 'Bosner MS et al. Percent cholesterol absorption in normal women and men quantified with dual stable isotopic tracers. J Lipid Res 1999;40:302-8')
